        question = makeQuestion(idNumber, "Hikâye unsurları", "Orta", storyText, "Bu metinde olayın gerçekleştiği yer aşağıdakilerden hangisidir?", place, [places[(occurrence + 5) % places.length], places[(occurrence + 9) % places.length], places[(occurrence + 13) % places.length]], "Olayın geçtiği yer metnin ilk cümlesinde açıkça belirtilmiştir.", answer);
